// Diagnosis.js
import React, { useState } from "react";
import "./navright-diagnosis.css";
import { ReactComponent as ArrowLeft } from '../assets/icons/arrow-left.svg';
import { ReactComponent as Send } from '../assets/icons/send.svg';
import { ReactComponent as Gpt } from '../assets/icons/gpt.svg';
import { ReactComponent as Db } from '../assets/icons/database.svg';

export default function NavrightDiagnosis() {

    const [onOffRag, setOnOffRag] = useState(false);
    const [onOffMedicalDb, setOnOffMedicalDb] = useState(false);
    setOnOffRag = () => {
        console.log('hello')
        return !onOffRag;
    }
    setOnOffMedicalDb = () => {
        return !onOffMedicalDb;
    }

    return (
        <div className="nav__right">
            <div className="chatbox">
                <div className="chatbox__message"></div>
                <div className="chatbox__send">
                    <div className="chatbox__send--input"></div>
                    <div className="chatbox__send--func">
                        <div className='chatbox__send--advance'>
                            <div className='chatbox__send--rag chatbox__send--advance-position'>
                                <Gpt className="icon--element icon-advance" />
                                RAG
                                <div className='button-on-off' onClick={setOnOffRag()}>
                                    <div className='circle-on-off'></div>
                                </div>
                            </div>
                            <div className='chatbox__send--db chatbox__send--advance-position'>
                                <Db className="icon--element icon-advance" />
                                Medical DB
                                <div id="on" className='button-on-off'>
                                    <div id="on-circle" className='circle-on-off'></div>
                                </div>
                            </div>
                        </div>
                        <button className='chatbox__send--button'>
                            <Send className="icon--element" />
                        </button>
                    </div>
                </div>
            </div>
            <div className="button-close-open-chat">
                <button>
                    <ArrowLeft className="icon--element" />
                </button>
            </div>
            <div className="acne-detection">
                hi
            </div>
        </div>
    );
};
